-- PT117-S4-Q13. Batch 09.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch09$PT117-S4-Q13$batch09$ AND q.stimulus=$batch09$Whether a machine performs its intended function is plain for all to see, but recognition of excellence in art requires a rare subtlety of perception. So whereas engineers usually maintain their composure when their work is being evaluated, artists tend to become anxious under such circumstances.$batch09$ AND q.prompt=$batch09$The reasoning above conforms most closely to which one of the following propositions?$batch09$ AND q.correct_choice=$batch09$D$batch09$) THEN RAISE EXCEPTION 'Question changed: PT117-S4-Q13'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch09$PT117-S4-Q13$batch09$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT117-S4-Q13'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch09$PT117-S4-Q13$batch09$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch09$Conclusion$batch09$, $batch09$Engineers usually stay calm when their work is evaluated, while artists tend to get anxious.$batch09$), (1, $batch09$Evidence$batch09$, $batch09$Anyone can see whether a machine works. Recognizing excellence in art takes rare, subtle perception.$batch09$), (2, $batch09$Evaluate$batch09$, $batch09$The argument explains a difference in anxiety by a difference in how easy the work is to judge. Easy to judge, calm creator. Hard to judge, anxious creator. The principle should be general: about people who create things, not just engineers and artists.$batch09$), (3, $batch09$Goal$batch09$, $batch09$People whose work's success is easy to see worry less about evaluations than people whose work's value is hard to see.$batch09$)) v(position,label,body) WHERE q.qid=$batch09$PT117-S4-Q13$batch09$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch09$A$batch09$, $batch09$The argument puts the anxiety down to the work being hard to judge, not to anyone's personality. A makes a claim about personalities that the argument never makes.$batch09$), ($batch09$B$batch09$, $batch09$This is the trap, picked by 5%. It mentions the creators' feelings, so it sounds close. But it says a work's value depends on those feelings. The argument says the creators' feelings depend on how easily the work can be judged. B reverses which one depends on which.$batch09$), ($batch09$C$batch09$, $batch09$The argument explains why artists get anxious. It never says how engineers or artists should be evaluated.$batch09$), ($batch09$D$batch09$, $batch09$Machines are things whose success is easily ascertained, and art is something whose value isn't. Engineers worry less and artists worry more. D is the stimulus stated in general terms.$batch09$), ($batch09$E$batch09$, $batch09$The argument compares two kinds of creators. E compares a creator to the evaluators. The stimulus never says how confident evaluators are.$batch09$)) v(letter,body) WHERE q.qid=$batch09$PT117-S4-Q13$batch09$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
